const quizAnswers=JSON.parse(localStorage.getItem('apklab-quiz-v2')||'{}');
function quizV2Html(id){const base=lessons[id][3];const qs=[...(base?[base]:[]),...(extraQuestions[id]||[])];if(!qs.length)return '';return '<section class="quiz quiz-v2"><span class="eyebrow">CHECKPOINT OPCIONAL</span><h3>Teste seus conhecimentos</h3><p>Responda para aprender. O quiz não bloqueia o avanço.</p><div class="quiz-score" id="quizScore">0/'+qs.length+' acertos</div>'+qs.map((q,i)=>'<div class="quiz-question"><p><strong>'+(i+1)+'.</strong> '+escapeHtml(q[0])+'</p>'+q[1].map((opt,j)=>'<button class="option" data-q="'+i+'" data-opt="'+j+'">'+String.fromCharCode(65+j)+'. '+escapeHtml(opt)+'</button>').join('')+'<div class="quiz-feedback" data-feedback="'+i+'" aria-live="polite"></div></div>').join('')+'<button class="btn quiz-reset" type="button">↺ Refazer checkpoint</button></section>'}
function wireQuizV2(id){const root=document.querySelector('.quiz-v2');if(!root)return;const qs=[...(lessons[id][3]?[lessons[id][3]]:[]),...(extraQuestions[id]||[])];const key='lesson-'+id;const saved=quizAnswers[key]||{};function paint(){let correct=0;qs.forEach((q,i)=>{const selected=saved[i];const answered=selected!==undefined;if(selected===q[2])correct++;root.querySelectorAll('[data-q="'+i+'"]').forEach(b=>{const opt=Number(b.dataset.opt);b.disabled=answered;b.classList.toggle('correct',answered&&opt===q[2]);b.classList.toggle('incorrect',answered&&opt===selected&&opt!==q[2]);});root.querySelector('[data-feedback="'+i+'"]').textContent=answered?(selected===q[2]?'✓ Correto! ':'Ainda não. ')+q[3]:''});root.querySelector('#quizScore').textContent=correct+'/'+qs.length+' acertos · '+Object.keys(saved).length+' respondidas'}root.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.q);if(saved[i]!==undefined)return;saved[i]=Number(b.dataset.opt);quizAnswers[key]=saved;localStorage.setItem('apklab-quiz-v2',JSON.stringify(quizAnswers));paint()});root.querySelector('.quiz-reset').onclick=()=>{delete quizAnswers[key];localStorage.setItem('apklab-quiz-v2',JSON.stringify(quizAnswers));go(id)};paint()}
function conceptCardsHtml(id){if(![0,1,2,3,8,14,15,17].includes(id))return '';const cards=id<4?[['APK','Pacote instalável para testes diretos no Android.'],['AAB','Pacote para distribuição pela Google Play.'],['Build','Processo que transforma o projeto em artefato instalável.']]:[['Diagnóstico','Verifica compatibilidade, mas não substitui testes.'],['Preview','Perfil de compilação para testes internos.'],['Keystore','Chave de assinatura que deve ser preservada.']];return '<section class="concepts"><h2>Cartões de revisão</h2><div class="concept-grid">'+cards.map(([a,b])=>'<button type="button" class="concept-card" aria-pressed="false"><strong>'+a+'</strong><span class="concept-front">Toque para revelar ↻</span><span class="concept-back" hidden>'+b+'</span></button>').join('')+'</div></section>'}
function wireConceptCards(){document.querySelectorAll('.concept-card').forEach(b=>b.onclick=()=>{const open=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',String(!open));b.querySelector('.concept-front').hidden=!open;b.querySelector('.concept-back').hidden=open})}

