function reviewTile(icon,title,description){return '<div class="review-tile"><span class="review-tile-icon" aria-hidden="true">'+icon+'</span><div><h3>'+title+'</h3><p>'+description+'</p></div></div>'}
function reviewInfographics(){location.hash='revisao';document.getElementById('crumb').textContent='Infográficos';main.innerHTML=`<div class="lesson-header"><span class="eyebrow">MATERIAL DE APOIO • CONSULTA LIVRE</span><h1>Central de revisão</h1><p>Revise os fundamentos e o passo a passo para gerar seu APK. O conteúdo funciona diretamente no site, sem depender de imagens externas.</p></div><nav class="review-jump" aria-label="Materiais de revisão"><a href="#revisao-fundamentos">01 • Fundamentos</a><a href="#revisao-pratica">02 • Passo a passo</a></nav><section class="review-section" id="revisao-fundamentos"><div class="review-section-head"><span class="eyebrow">01 • TEORIA</span><h2>Fundamentos do APK</h2><p>Entenda os conceitos antes de executar os comandos.</p></div><div class="review-flow"><span>💻 Projeto Expo</span><b>→</b><span>☁️ EAS Build</span><b>→</b><span>📦 APK</span><b>→</b><span>📱 Android</span></div><div class="review-fund-grid">${reviewFundamentals.map(x=>reviewTile(...x)).join('')}</div><p class="review-reminder"><strong>Lembre-se:</strong> build concluído não significa aplicativo testado. Instale e confira as funções no celular.</p></section><section class="review-section" id="revisao-pratica"><div class="review-section-head"><span class="eyebrow">02 • PRÁTICA</span><h2>Passo a passo para gerar o APK</h2><p>Siga a sequência. Os comandos são exemplos para executar no terminal da pasta do projeto.</p></div><div class="review-steps">${reviewSteps.map((x,i)=>'<article class="review-step"><span class="review-step-number">'+String(i+1).padStart(2,'0')+'</span><div><h3>'+x[0]+'</h3><p>'+x[1]+'</p>'+(x[2]?'<pre><code>'+escapeHtml(x[2])+'</code></pre>':'')+'</div></article>').join('')}</div><p class="review-reminder"><strong>Importante:</strong> o QR Code de desenvolvimento do Expo Go não é o mesmo que o acesso ao APK final. O download fica disponível após o build terminar.</p></section><div class="lesson-bottom"><button class="btn primary" id="backFromReview">← Voltar ao início</button></div>`;document.getElementById('backFromReview').onclick=home;document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));window.scrollTo({top:0,behavior:'smooth'});closeMenu();document.querySelectorAll('.review-jump a').forEach(link=>link.onclick=e=>{e.preventDefault();document.getElementById(link.getAttribute('href').slice(1)).scrollIntoView({behavior:'smooth',block:'start'})})}
function go(id){if(!Number.isInteger(id)||id<0||id>=lessons.length){location.hash='inicio';hero();return}location.hash='etapa-'+(id+1);const l=lessons[id];document.getElementById('crumb').textContent=l[0];main.innerHTML=`<div class="lesson-header"><span class="eyebrow">ETAPA ${String(id+1).padStart(2,'0')} / ${lessons.length} • ${modules.find(m=>m.ids.includes(id)).name.toUpperCase()}</span><h1>${l[0]}</h1><p>${l[1]}</p></div><article class="content">${l[2]}${deepDiveHtml(id)}${conceptCardsHtml(id)}${labExtrasHtml(id)}</article>${quizV2Html(id)}<div class="lesson-bottom">${id>0?`<button class="btn" id="prev">← Anterior</button>`:`<button class="btn" id="prev">← Início</button>`}<button class="btn primary" id="complete">${state.done.has(id)?'✓ Concluída — continuar':'✓ Marcar como concluída e continuar'} →</button></div>`;document.getElementById('prev').onclick=()=>id?go(id-1):home();document.getElementById('complete').onclick=()=>{state.done.add(id);persist();toast('Etapa concluída!');id<lessons.length-1?go(id+1):home()};document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',Number(b.dataset.go)===id));document.querySelectorAll('[data-check]').forEach(x=>{x.checked=!!state.checks[x.dataset.check];x.onchange=()=>{state.checks[x.dataset.check]=x.checked;persist()}});document.querySelectorAll('.copy-code').forEach(b=>b.onclick=async()=>{let v=decodeURIComponent(b.dataset.copy);try{await navigator.clipboard.writeText(v);toast('Código copiado!')}catch{toast('Selecione o código e copie com Ctrl+C')}});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let correct=Number(b.dataset.answer)===l[3][2];document.querySelectorAll('[data-answer]').forEach(o=>{o.classList.remove('correct','incorrect');if(Number(o.dataset.answer)===l[3][2])o.classList.add('correct')});if(!correct)b.classList.add('incorrect');document.getElementById('feedback').innerHTML=`<div class="feedback">${correct?'✓ Muito bem!':'↻ Quase!'} ${l[3][3]}</div>`});wireQuizV2(id);wireConceptCards();window.scrollTo({top:0,behavior:'smooth'});closeMenu()}
function home(){location.hash='inicio';hero();renderNav();window.scrollTo({top:0,behavior:'smooth'});closeMenu()}
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').classList.remove('visible')}
let toastTimer;function toast(msg){let e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2400)}
document.getElementById('menuBtn').onclick=()=>{document.getElementById('sidebar').classList.toggle('open');document.getElementById('overlay').classList.toggle('visible')};document.getElementById('overlay').onclick=closeMenu;document.querySelector('.brand').onclick=e=>{e.preventDefault();home()};document.getElementById('themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.body.classList.toggle('light',state.theme==='light');localStorage.setItem('apklab-theme',state.theme)};document.getElementById('resetBtn').onclick=()=>{if(confirm('Deseja apagar o progresso e os checklists deste navegador?')){state.done.clear();state.checks={};Object.keys(quizAnswers).forEach(k=>delete quizAnswers[k]);localStorage.removeItem('apklab-quiz-v2');persist();home();toast('Progresso reiniciado')}};
const searchDialog=document.getElementById('searchDialog'),glossaryDialog=document.getElementById('glossaryDialog');document.getElementById('searchBtn').onclick=()=>{searchDialog.showModal();document.getElementById('searchInput').focus();search()};document.getElementById('reviewBtn').onclick=reviewInfographics;document.getElementById('glossaryBtn').onclick=()=>{document.getElementById('glossaryContent').innerHTML=Object.entries(glossary).map(([k,v])=>`<div class="glossary-entry"><strong>${k==='ReactNative'?'React Native':k}</strong><p>${v}</p></div>`).join('');glossaryDialog.showModal()};document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.getElementById('searchInput').oninput=search;function search(){let q=document.getElementById('searchInput').value.toLowerCase().trim();let res=lessons.map((l,i)=>({l,i})).filter(({l})=>!q||l[0].toLowerCase().includes(q)||l[1].toLowerCase().includes(q)||l[2].replace(/<[^>]+>/g,' ').toLowerCase().includes(q)).slice(0,15);document.getElementById('searchResults').innerHTML=res.length?res.map(({l,i})=>`<button class="search-result" data-search-go="${i}">${l[0]}<small>Etapa ${i+1} · ${l[1]}</small></button>`).join(''):'<p>Nenhuma etapa encontrada.</p>';document.querySelectorAll('[data-search-go]').forEach(b=>b.onclick=()=>{searchDialog.close();go(Number(b.dataset.searchGo))})}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog.showModal();document.getElementById('searchInput').focus();search()}});renderNav();const match=location.hash.match(/^#etapa-(\d+)$/);match?go(Number(match[1])-1):location.hash==='#revisao'?reviewInfographics():home();